files.system/blockMeshDict:
FoamFile
{
    format ascii;
    class dictionary;
    object blockMeshDict;
}

vertices
(
    (0 0 -0.0005) (0.3 0 -0.0005) (0.3 0.005 -0.0005) (0 0.005 -0.0005)
    (0 0 0.0005) (0.3 0 0.0005) (0.3 0.005 0.0005) (0 0.005 0.0005)
);
blocks
(
    hex (0 1 2 3 4 5 6 7) (150 60 1) simpleGrading (1 1 1)
);
defaultPatch { type empty; }
boundary
(
    inlet { type patch; faces ((0 3 7 4)); }
    outlet { type patch; faces ((1 2 6 5)); }
    walls { type wall; faces ((0 1 5 4) (3 2 6 7)); }
    frontAndBack { type empty; faces ((0 1 2 3) (4 5 6 7)); }
);

files.system/controlDict:
FoamFile
{
    format ascii;
    class dictionary;
    object controlDict;
}

solver          incompressibleFluid;
startFrom       startTime;
startTime       0;
stopAt          endTime;
endTime         2000;
deltaT          1;
writeControl    timeStep;
writeInterval   20;
purgeWrite      0;
writeFormat     ascii;
writePrecision  8;
writeCompression off;
timeFormat      general;
timePrecision   6;
runTimeModifiable true;

files.system/fvSchemes:
FoamFile
{
    format ascii;
    class dictionary;
    object fvSchemes;
}

ddtSchemes
{
    default steadyState;
}

gradSchemes
{
    default Gauss linear;
}

divSchemes
{
    default none;
    div(phi,U) bounded Gauss linearUpwind grad(U);
}

laplacianSchemes
{
    default Gauss linear corrected;
}

interpolationSchemes
{
    default linear;
}

snGradSchemes
{
    default corrected;
}

files.system/fvSolution:
FoamFile
{
    format ascii;
    class dictionary;
    object fvSolution;
}

solvers
{
    p
    {
        solver          GAMG;
        tolerance       1e-09;
        relTol          0.01;
        smoother        GaussSeidel;
    }

    pFinal
    {
        $p;
        tolerance       1e-09;
        relTol          0;
    }

    U
    {
        solver          smoothSolver;
        smoother        symGaussSeidel;
        tolerance       1e-10;
        relTol          0.1;
    }
}

SIMPLE
{
    nNonOrthogonalCorrectors 0;
    consistent      yes;

    residualControl
    {
        p   1e-8;
        U   1e-9;
    }
}

relaxationFactors
{
    equations
    {
        U   0.9;
        ".*" 0.9;
    }
}

files.constant/physicalProperties:
FoamFile
{
    format ascii;
    class dictionary;
    object physicalProperties;
}

viscosityModel  constant;

nu              1.004e-06 [m^2/s];

files.constant/momentumTransport:
FoamFile
{
    format ascii;
    class dictionary;
    object momentumTransport;
}

simulationType laminar;

files.0/U:
FoamFile
{
    format ascii;
    class volVectorField;
    object U;
}

dimensions [velocity];
internalField uniform (0.02 0 0);
boundaryField
{
    inlet { type fixedValue; value uniform (0.02 0 0); }
    outlet { type zeroGradient; }
    walls { type noSlip; }
    frontAndBack { type empty; }
}

files.0/p:
FoamFile
{
    format ascii;
    class volScalarField;
    object p;
}

dimensions [kinematicPressure];
internalField uniform 0;
boundaryField
{
    inlet { type zeroGradient; }
    outlet { type fixedValue; value uniform 0; }
    walls { type zeroGradient; }
    frontAndBack { type empty; }
}
